output_text:
[
  {
    "id": "no_carts_in_narrow_shelf_aisles",
    "text": "Shopping carts are not allowed in the narrow shelf aisles where shelves are immediately on both sides.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "narrowShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_entering_narrow_aisle",
    "text": "Before entering a narrow shelf aisle, a shopper must leave the cart outside rather than moving into the aisle with it.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterNarrowAisleWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "narrowShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterNarrowAisleWithCart"
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks or releases a cart, they are obliged to retrieve a cart again before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "drop_cart_only_at_aisle_mouth",
    "text": "Carts may be parked only at designated aisle-mouth parking spots outside narrow aisles.",
    "abstraction": {
      "state_properties": {
        "aisleMouthCartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "aisleMouthCartPark"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_open_shelf_service",
    "text": "Shelf interactions from cart-accessible open aisles must be performed while holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "narrowShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartAccessibleShelf": {
          "and": [
            "adjShelf",
            {
              "not": "narrowShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "cartAccessibleShelf",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_open_aisle_travel",
    "text": "Except at the entrance cart bay or a cart-parking aisle mouth, shoppers should not walk through open aisles without a cart.",
    "abstraction": {
      "state_properties": {
        "openAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "cartlessExceptionArea": {
          "or": [
            "at(0,7)",
            "at(1,7)",
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "openAisle",
          {
            "not": "cartlessExceptionArea"
          }
        ]
      }
    }
  },
  {
    "id": "one_way_east_in_broad_aisles",
    "text": "Broad horizontal aisles are one-way eastbound, so westward movement in them is forbidden.",
    "abstraction": {
      "state_properties": {
        "broadHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "W",
          "broadHorizontalAisle"
        ]
      }
    }
  },
  {
    "id": "take_cart_from_entrance_bay",
    "text": "At the beginning of a shopping trip, the shopper is obliged to collect a cart from the entrance cart bay before continuing the shopping task.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": "at(1,7)"
      },
      "events": {
        "collectCartAtEntrance": {
          "pre": {
            "and": [
              "INTERACT",
              "entranceCartBay",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collectCartAtEntrance"
    }
  }
]
